import{_ as o,a0 as n,w as l,s as p,I as i,x as a,a1 as r,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"如何在 Fedora Linux 上安裝 Brave 瀏覽器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安裝 Brave 瀏覽器 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安裝 Brave 瀏覽器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安裝 Brave 瀏覽器 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS","title":"如何在 Fedora Linux 上安裝 Brave 瀏覽器","tag":"202111","desc":""},"relativePath":"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS.md","filePath":"[post].md"}'),u={name:"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS.md"};function b(g,e,h,m,f,v){const s=n("Link");return l(),p("div",null,[e[19]||(e[19]=i("h1",{id:"如何在-fedora-linux-上安裝-brave-瀏覽器",tabindex:"-1"},[a("如何在 Fedora Linux 上安裝 Brave 瀏覽器 "),i("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安裝-brave-瀏覽器","aria-label":"Permalink to “如何在 Fedora Linux 上安裝 Brave 瀏覽器”"},"​")],-1)),e[20]||(e[20]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/28/102349idh316xz3bslr6ps.jpg",alt:""})],-1)),i("p",null,[r(s,{href:"https://brave.com/"},{default:t(()=>[...e[0]||(e[0]=[a("Brave",-1)])]),_:1}),e[2]||(e[2]=a(" 是一個越來越 ",-1)),r(s,{href:"https://itsfoss.com/best-browsers-ubuntu-linux/"},{default:t(()=>[...e[1]||(e[1]=[a("流行於 Linux",-1)])]),_:1}),e[3]||(e[3]=a(" 和其他操作系統的網頁瀏覽器。對默認情況下阻止廣告和跟蹤的關注，以及對 Chrome 擴展的支持，使 Brave 成為 Linux 用户的熱門選擇。",-1))]),e[21]||(e[21]=d('<p>在本教程中，你將學習如何在 Fedora Linux 上安裝 Brave。你還將學習如何更新和刪除它。</p><p>本教程已經在 Fedora 上進行了測試，但它也應該適用於基於 Red Hat 的其他發行版，如 CentOS、Alma Linux 和 Rocky Linux。</p><h3 id="在-fedora-linux-上安裝-brave-瀏覽器" tabindex="-1">在 Fedora Linux 上安裝 Brave 瀏覽器 <a class="header-anchor" href="#在-fedora-linux-上安裝-brave-瀏覽器" aria-label="Permalink to “在 Fedora Linux 上安裝 Brave 瀏覽器”">​</a></h3><p>你需要在這裏用命令列的方式來安裝 Brave。</p><p>作為先決條件，請確保 <code>dnf-plugin-core</code> 已經安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install dnf-plugins-core</span></span></code></pre></div><p>下一步是將 Brave 倉庫添加到你的系統中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf config-manager --add-repo https://brave-browser-rpm-release.s3.brave.com/x86_64/</span></span></code></pre></div><p>你還應該導入並添加倉庫密鑰，這樣你的系統就會信任來自這個新添加的倉庫的軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm --import https://brave-browser-rpm-release.s3.brave.com/brave-core.asc</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/adding-Brave-browser-repository-in-Fedora.png?resize=800%2C300&amp;ssl=1" alt="Adding Brave Browser repository in Fedora Linux"></p><p>現在可以開始了。用這個命令安裝 Brave：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install brave-browser</span></span></code></pre></div><p><strong>當被要求確認你的選擇時按 <code>Y</code></strong>。根據你的網速，這應該需要幾秒鐘或幾分鐘的時間。如果 DNF 的緩存最近沒有更新，甚至可能需要更長時間。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/Installing-Brave-Browser-Fedora.png?resize=800%2C428&amp;ssl=1" alt="Installing Brave Browser in Fedora"></p><p>安裝完成後，在系統菜單中尋找 Brave 並從那裏啓動。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/start-brave-fedora-linux.png?resize=759%2C219&amp;ssl=1" alt="Start Brave browser in Fedora Linux"></p><h3 id="在-fedora-linux-上更新-brave-瀏覽器" tabindex="-1">在 Fedora Linux 上更新 Brave 瀏覽器 <a class="header-anchor" href="#在-fedora-linux-上更新-brave-瀏覽器" aria-label="Permalink to “在 Fedora Linux 上更新 Brave 瀏覽器”">​</a></h3><p>你已經為瀏覽器添加了一個倉庫，並且導入了它的密鑰。你的系統信任來自這個倉庫的軟件包。</p><p>因此，當有新的 Brave 瀏覽器發佈並提供給這個倉庫時，你會通過常規的系統升級得到它。</p><p>換句話説，你不需要做任何特別的事情。只要保持你的 Fedora 系統更新，如果有 Brave 的新版本，它應該會隨着系統更新自動安裝。</p><h3 id="從-fedora-linux-中刪除-brave-瀏覽器" tabindex="-1">從 Fedora Linux 中刪除 Brave 瀏覽器 <a class="header-anchor" href="#從-fedora-linux-中刪除-brave-瀏覽器" aria-label="Permalink to “從 Fedora Linux 中刪除 Brave 瀏覽器”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/Brave-Browser-in-Fedora-Linux.png?resize=800%2C530&amp;ssl=1" alt="Brave Browser in Fedora Linux"></p><p>如果你因為某些原因不喜歡 Brave，你可以從你的系統中刪除它。只需使用 <code>dnf remove</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove brave-browser</span></span></code></pre></div><p>當詢問時按 <code>Y</code>：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/removing-Brave-browser-Fedora-Linux.png?resize=800%2C399&amp;ssl=1" alt="Removing Brave browser from Fedora Linux"></p><p>你也可以選擇禁用 <code>brave-browser-rpm-release.s3.brave.com_x86_64_.repo</code> 或者從 <code>/etc/yum/repos.d</code> 中完全刪除這個文件，雖然這並不是必須的。</p><p>我希望這個快速提示對你有幫助。如果你有任何問題或建議，請讓我知道。</p><hr>',30)),i("p",null,[e[5]||(e[5]=a("via: ",-1)),r(s,{href:"https://itsfoss.com/install-brave-browser-fedora/"},{default:t(()=>[...e[4]||(e[4]=[a("https://itsfoss.com/install-brave-browser-fedora/",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=a("作者：",-1)),r(s,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...e[6]||(e[6]=[a("Abhishek Prakash",-1)])]),_:1}),e[11]||(e[11]=a(" 選題：",-1)),r(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[7]||(e[7]=[a("lujun9972",-1)])]),_:1}),e[12]||(e[12]=a(" 譯者：",-1)),r(s,{href:"https://github.com/geekpi"},{default:t(()=>[...e[8]||(e[8]=[a("geekpi",-1)])]),_:1}),e[13]||(e[13]=a(" 校對：",-1)),r(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[9]||(e[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=a("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原創編譯，",-1)),r(s,{href:"https://linux.cn/"},{default:t(()=>[...e[15]||(e[15]=[a("Linux中國",-1)])]),_:1}),e[18]||(e[18]=a(" 榮譽推出",-1))])])}const c=o(u,[["render",b]]);export{B as __pageData,c as default};
